#include <iostream>
using namespace std;

int main() {
    int choice;
    do {
        cout << "1. Say hello" << endl;
        cout << "2. Quit" << endl;
        cout << "Choice: ";
        cin >> choice;
        switch (choice) {
            case 1: cout << "Hello from my project!" << endl; break;
            case 2: cout << "Bye!" << endl; break;
            default: cout << "Invalid choice" << endl;
        }
    } while (choice != 2);
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

struct Student {
    int id;
    string name;
    double marks;
};

int main() {
    Student s = {101, "Ayesha", 88.5};
    cout << "ID: " << s.id << endl;
    cout << "Name: " << s.name << endl;
    cout << "Marks: " << s.marks << endl;
    if (s.marks >= 50) {
        cout << "Result: Pass" << endl;
    } else {
        cout << "Result: Fail" << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

void printBoard(char b[3][3]) {
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 3; c++) {
            cout << b[r][c];
            if (c < 2) {
                cout << " | ";
            }
        }
        cout << endl;
        if (r < 2) {
            cout << "---------" << endl;
        }
    }
}

bool rowWins(char b[3][3], int r, char p) {
    return b[r][0] == p && b[r][1] == p && b[r][2] == p;
}

int main() {
    char board[3][3] = {
        {'X', 'X', 'X'},
        {'O', 'O', '.'},
        {'.', '.', '.'}
    };
    printBoard(board);
    if (rowWins(board, 0, 'X')) {
        cout << "X wins on row 0" << endl;
    }
    return 0;
}

